CREATE TABLE cottages (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  sleeps INTEGER NOT NULL CHECK (sleeps > 0),
  nightly_rate REAL NOT NULL
);
INSERT INTO cottages (name, sleeps, nightly_rate)
SELECT name, sleeps, nightly_rate FROM cottage_sheet ORDER BY name;

CREATE TABLE guests (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE
);
INSERT INTO guests (name, email)
SELECT MIN(guest_name), guest_email FROM requests GROUP BY guest_email ORDER BY guest_email;

CREATE TABLE bookings (
  id INTEGER PRIMARY KEY,
  guest_id INTEGER NOT NULL REFERENCES guests (id),
  cottage_id INTEGER NOT NULL REFERENCES cottages (id),
  arrive TEXT NOT NULL,
  depart TEXT NOT NULL,
  party INTEGER NOT NULL CHECK (party > 0),
  CHECK (depart > arrive)
);

INSERT INTO bookings (guest_id, cottage_id, arrive, depart, party)
SELECT g.id, c.id, r.arrive, r.depart, r.party
FROM requests r
JOIN guests g ON g.email = r.guest_email
JOIN cottages c ON c.name = r.cottage
WHERE r.party <= c.sleeps
ORDER BY r.id;

DELETE FROM bookings
WHERE EXISTS (
  SELECT 1 FROM bookings a
  WHERE a.cottage_id = bookings.cottage_id
    AND a.id < bookings.id
    AND a.arrive < bookings.depart
    AND bookings.arrive < a.depart
);

CREATE INDEX bookings_cottage_arrive ON bookings (cottage_id, arrive);

